"use strict";

// The NEGATIVE controls that make RWF-023 sound rather than merely
// permissive. Every computed key below is written EXACTLY as the ones in
// index.js and forms.js, and not one of them runs during module
// evaluation, because the class DEFINITION that would evaluate them is
// itself in a deferred position.
//
// This is the half a "root every computed key in the file" implementation
// gets wrong, and it is why RWF-023 walks from the class up to the
// walk's current owner and refuses as soon as it crosses a deferred
// position, instead of treating every computed key as top-level.
//
// Nothing in this module calls any of these, so on a real load the sink
// is never reached -- proven in-process by the ground-truth fixture.
const danger = require("./danger");

function key() {
  danger.explode("deferred-key");
  return "x";
}

// 1. A class inside a function declaration nothing calls at module scope.
function configure() {
  class InsideFunction {
    [key()]() {}
  }
  return InsideFunction;
}

// 2. A class inside an arrow body nothing calls.
const configureArrow = () => {
  class InsideArrow {
    [key()]() {}
  }
  return InsideArrow;
};

// 3. A class inside a callback passed to a function that never invokes it.
function neverInvokes(callback) {
  return typeof callback;
}
neverInvokes(function () {
  class InsideCallback {
    [key()]() {}
  }
  return InsideCallback;
});

class Host {
  // 4. A class inside a METHOD body -- deferred until the method is called.
  method() {
    class InsideMethod {
      [key()]() {}
    }
    return InsideMethod;
  }

  // 5. A class inside a GETTER body -- deferred until the property is read.
  get accessor() {
    class InsideGetter {
      [key()]() {}
    }
    return InsideGetter;
  }

  // 6. A class inside a CONSTRUCTOR body -- deferred until construction.
  constructor() {
    class InsideConstructor {
      [key()]() {}
    }
    this.inner = InsideConstructor;
  }

  // 7. A nested class held by an INSTANCE FIELD. The field's VALUE is
  //    evaluated per-instance during construction, so `Nested` is not
  //    defined at class-definition time and its key does not run. This is
  //    the critical false-AFFECTED control: the enclosing class IS being
  //    defined at module load, and a naive "the class is at module scope"
  //    rule roots this one wrongly.
  field = class Nested {
    [key()]() {}
  };

  // 8. The same shape one level further in: an object literal, itself in
  //    an instance field, holding a computed method key.
  literal = {
    [key()]() {},
  };
}

// 9. A method whose PARAMETER DEFAULT holds a class. Defaults are
//    evaluated per-call, not at definition time.
class Defaults {
  method(inner = class Param { [key()]() {} }) {
    return inner;
  }
  set accessor(value = class Param2 { [key()]() {} }) {
    this.stored = value;
  }
}

module.exports = { configure, configureArrow, Host, Defaults };
